// Independent re-derivation of the per-family RAM rates + pooled vCPU rate
// from the prior agent's CSV dump, plus the monotonicity + floor checks.
// Pure computation over local files; no DB, no network.
import fs from "fs";

const csv = fs.readFileSync("/root/nxeon-phase-custom-game-pricing/gameplans.csv", "utf8").trim().split("\n");
const fams = {};
for (const l of csv) {
  const [f, c, r, d, p] = l.split(",");
  (fams[f] ??= []).push({ cpu: +c, ram: +r / 1024, disk: +d, price: +p });
}

// Parse the committed table straight out of the branch source file.
const src = fs.readFileSync("/root/nxeon-worktrees/pricing-review/lib/custom-plan-pricing.ts", "utf8");
const block = src.split("CUSTOM_GAME_PLAN_DEFAULT_RAM_GB_CENTS: Record<string, number> = {")[1].split("};")[0];
const table = {};
for (const m of block.matchAll(/(\w+):\s*(\d+)/g)) table[m[1]] = +m[2];

const DISK = 10;
console.log("families in CSV:", Object.keys(fams).length, " rows:", csv.length, " families in table:", Object.keys(table).length);
const missingInTable = Object.keys(fams).filter((f) => !(f in table));
const extraInTable = Object.keys(table).filter((f) => !(f in fams));
console.log("in CSV not table:", missingInTable, " in table not CSV:", extraInTable);

// deltas sorted by price (the code's anchor = max price)
const deltas = {};
for (const [f, ts] of Object.entries(fams)) {
  ts.sort((a, b) => a.price - b.price);
  deltas[f] = [];
  for (let i = 1; i < ts.length; i++) {
    const a = ts[i - 1], b = ts[i];
    deltas[f].push({ dc: b.cpu - a.cpu, dr: b.ram - a.ram, dd: b.disk - a.disk, dp: b.price - a.price });
  }
  // sanity: price-sorted order also RAM-sorted? any tier dominated weirdly?
  for (let i = 1; i < ts.length; i++) {
    if (ts[i].ram < ts[i - 1].ram || ts[i].cpu < ts[i - 1].cpu || ts[i].disk < ts[i - 1].disk)
      console.log(`  NOTE non-monotone spec in price order: ${f}`, ts[i - 1], ts[i]);
    if (ts[i].price === ts[i - 1].price) console.log(`  NOTE price tie in ${f}`);
  }
}

// FWL pooled vCPU rate
let scc = 0, src2 = 0, n = 0;
for (const ds of Object.values(deltas)) {
  if (ds.length < 2) continue;
  const szz = ds.reduce((s, d) => s + d.dr * d.dr, 0);
  const scz = ds.reduce((s, d) => s + d.dc * d.dr, 0);
  const spz = ds.reduce((s, d) => s + (d.dp - DISK * d.dd) * d.dr, 0);
  for (const d of ds) {
    const ct = d.dc - (scz / szz) * d.dr;
    const rt = d.dp - DISK * d.dd - (spz / szz) * d.dr;
    scc += ct * ct; src2 += rt * ct; n++;
  }
}
const A = src2 / scc;
console.log(`pooled points=${n}  raw vCPU rate=${A.toFixed(3)}  rounded=${Math.round(A)}`);

// per-family RAM rate with a=111
const a = 111;
let mismatches = 0;
const rows = [];
for (const [f, ds] of Object.entries(deltas)) {
  const szz = ds.reduce((s, d) => s + d.dr * d.dr, 0);
  const syz = ds.reduce((s, d) => s + (d.dp - DISK * d.dd - a * d.dc) * d.dr, 0);
  const b = syz / szz;
  if (Math.round(b) !== table[f]) { mismatches++; console.log(`  MISMATCH ${f}: recomputed ${b.toFixed(2)} vs table ${table[f]}`); }
  // in-sample fit error: predict each tier from the top tier using the formula
  const ts = fams[f];
  const top = ts[ts.length - 1];
  const errs = ts.slice(0, -1).map((t) => {
    const pred = top.price + (t.cpu - top.cpu) * a + (t.ram - top.ram) * table[f] + (t.disk - top.disk) * DISK;
    return ((pred - t.price) / t.price * 100).toFixed(0) + "%";
  });
  rows.push({ f, b: table[f], nTiers: ts.length, backcastErr: errs.join(" ") });
}
console.log("table mismatches:", mismatches);

// Monotonicity: brute-force the spec grid for every family under both possible
// VPS-Max prices (3299 per code comment, 4750 per derivation script / old $55.30 math).
for (const vpsMax of [{ c: 4, r: 16, d: 120, p: 3299 }, { c: 4, r: 16, d: 120, p: 4750 }]) {
  let viol = 0, flatRuns = 0;
  for (const [f, ts] of Object.entries(fams)) {
    const top = ts[ts.length - 1];
    const floor = { c: Math.max(vpsMax.c, top.cpu), r: Math.max(vpsMax.r, top.ram), d: Math.max(vpsMax.d, top.disk) };
    const price = (c, r, d) => Math.max(Math.round(top.price + (c - top.cpu) * a + (r - top.ram) * table[f] + (d - top.disk) * DISK), vpsMax.p + 1, top.price + 1);
    for (let c = floor.c; c <= 32; c++) for (let r = floor.r; r <= 128; r++) for (let d = floor.d; d <= 2000; d += 10) {
      const p = price(c, r, d);
      // never below/equal ANY premade tier of this family, nor VPS Max
      for (const t of ts) if (p <= t.price) viol++;
      if (p <= vpsMax.p) viol++;
      // monotone in each dimension
      if (c > floor.c && price(c - 1, r, d) > p) viol++;
      if (r > floor.r && price(c, r - 1, d) > p) viol++;
    }
    // how far does the price stay pinned at the VPS-Max clamp along the RAM axis?
    let pinned = 0;
    for (let r = floor.r; r <= 128; r++) if (price(floor.c, r, floor.d) === vpsMax.p + 1) pinned++;
    if (pinned > 1) { flatRuns++; if (vpsMax.p === 4750) console.log(`  clamp-flat @Max=${vpsMax.p}: ${f} price pinned at $${(vpsMax.p + 1) / 100} for ${pinned} RAM-GB steps from floor`); }
  }
  console.log(`VPS Max price ${vpsMax.p}: monotonicity/undercut violations = ${viol}; families with a flat clamp region = ${flatRuns}`);
}

console.table(rows.sort((x, y) => x.f.localeCompare(y.f)));

