// Exercise the branch's ACTUAL pure pricing functions (copied verbatim from
// lib/custom-plan-pricing.ts) against the prod tier ladders in the CSV.
import fs from "fs";
import {
  CUSTOM_GAME_PLAN_DEFAULT_RAM_GB_CENTS as TABLE,
  CUSTOM_GAME_PLAN_DEFAULT_PER_VCPU_CENTS as VCPU,
  CUSTOM_PLAN_DEFAULT_CEILING as CEIL,
  computeCustomGamePlanPriceCents,
  gameCustomFloor,
  validateCustomPlanSpec,
  clampCustomPlanSpec,
  parseGameFamilyRatesOverride,
} from "./cpp.ts";

const fams: Record<string, { cpuCores: number; ramMB: number; diskGB: number; priceCents: number }[]> = {};
for (const l of fs.readFileSync("/root/nxeon-phase-custom-game-pricing/gameplans.csv", "utf8").trim().split("\n")) {
  const [f, c, r, d, p] = l.split(",");
  (fams[f] ??= []).push({ cpuCores: +c, ramMB: +r, diskGB: +d, priceCents: +p });
}

const gb = (mb: number) => Math.round(mb / 1024);
let problems = 0;
for (const vpsPrice of [3299, 4750]) {
  const vpsFloor = { cpuCores: 4, ramMB: 16384, diskGB: 120, priceCents: vpsPrice, bandwidthTB: 4 };
  let checked = 0;
  for (const [fam, tiers] of Object.entries(fams)) {
    // server: findFirst orderBy priceCents desc ; client: reduce(strict >)
    const top = [...tiers].sort((a, b) => b.priceCents - a.priceCents)[0];
    const clientTop = tiers.reduce((m, t) => (t.priceCents > m.priceCents ? t : m));
    if (top !== clientTop) { problems++; console.log("anchor mismatch", fam); }
    const anchor = { cpuCores: top.cpuCores, ramMB: top.ramMB, diskGB: top.diskGB, priceCents: top.priceCents };
    const floor = gameCustomFloor(vpsFloor, anchor);
    const rates = { perVcpuCents: VCPU, perRamGbCents: TABLE[fam], perDiskGbCents: 10 };
    for (let c = floor.cpuCores; c <= CEIL.maxCpuCores; c += 1)
      for (let r = gb(floor.ramMB); r <= gb(CEIL.maxRamMB); r += 1)
        for (let d = floor.diskGB; d <= CEIL.maxDiskGB; d += 10) {
          const spec = clampCustomPlanSpec({ cpuCores: c, ramMB: r * 1024, diskGB: d }, floor, CEIL);
          if (!validateCustomPlanSpec(spec, floor, CEIL).ok) continue;
          checked++;
          const price = computeCustomGamePlanPriceCents(spec, anchor, rates, vpsFloor.priceCents);
          // (1) never at/below any premade tier of this family or VPS Max
          if (tiers.some((t) => price <= t.priceCents) || price <= vpsFloor.priceCents) { problems++; console.log("UNDERCUT", fam, spec, price); }
          // (2) never smaller than the family's biggest tier on any dimension
          if (spec.cpuCores < top.cpuCores || spec.ramMB < top.ramMB || spec.diskGB < top.diskGB) { problems++; console.log("SMALLER THAN TOP", fam, spec); }
          // (3) the client breakdown (CustomServer.tsx) sums to the price
          const bc = Math.max(0, spec.cpuCores - anchor.cpuCores);
          const br = Math.max(0, gb(spec.ramMB - anchor.ramMB));
          const bd = Math.max(0, spec.diskGB - anchor.diskGB);
          const raw = anchor.priceCents + bc * rates.perVcpuCents + br * rates.perRamGbCents + bd * rates.perDiskGbCents;
          const platformMin = Math.max(0, price - raw);
          if (raw + platformMin !== price) { problems++; console.log("BREAKDOWN != PRICE", fam, spec, raw, platformMin, price); }
        }
  }
  console.log(`vpsMax=${vpsPrice}: checked ${checked} valid specs across ${Object.keys(fams).length} families`);
}

// Doc verification table, recomputed with the real function on the STAGING anchors the doc quotes
const stg = [
  { name: "rust", anchor: { cpuCores: 6, ramMB: 16384, diskGB: 130, priceCents: 6766 }, spec: { cpuCores: 10, ramMB: 23 * 1024, diskGB: 160 }, claimed: 9778 },
  { name: "squad", anchor: { cpuCores: 14, ramMB: 40960, diskGB: 110, priceCents: 10798 }, spec: { cpuCores: 15, ramMB: 42 * 1024, diskGB: 125 }, claimed: 11493 },
  { name: "minecraft", anchor: { cpuCores: 3, ramMB: 8192, diskGB: 50, priceCents: 1599 }, spec: { cpuCores: 6, ramMB: 23 * 1024, diskGB: 130 }, claimed: 5537 },
];
for (const s of stg) {
  const p = computeCustomGamePlanPriceCents(s.spec, s.anchor, { perVcpuCents: VCPU, perRamGbCents: TABLE[s.name], perDiskGbCents: 10 }, 3299);
  console.log(`doc-table ${s.name}: recomputed ${p} vs claimed ${s.claimed} ${p === s.claimed ? "OK" : "MISMATCH"}`);
}

// Original incident spec on PROD ladder
{
  const top = fams.rust.at(-1)!;
  const p = computeCustomGamePlanPriceCents({ cpuCores: 10, ramMB: 23 * 1024, diskGB: 120 }, top, { perVcpuCents: VCPU, perRamGbCents: TABLE.rust, perDiskGbCents: 10 }, 4750);
  console.log(`prod Rust 10c/23G/120G -> ${p} (old flat-VPS: 5530)`);
}

// parseGameFamilyRatesOverride edge cases
for (const j of ['{"rust":0}', '{"rust":-5}', '{"rust":"abc"}', '[1,2]', "null", '{"rust":0.4}', '{"rust":"  500 "}', '{"rust":1e400}', "{bad json", '{" rust ":999}']) {
  console.log(`override ${j.padEnd(18)} -> rust=${parseGameFamilyRatesOverride(j).rust}`);
}
console.log("TOTAL PROBLEMS:", problems);

