const fs=require("fs");
const seeds={};
for(const f of fs.readdirSync("prisma").filter(f=>/^seed.*\.ts$/.test(f))){
  const s=fs.readFileSync("prisma/"+f,"utf8");
  for(const m of s.matchAll(/gameFamily:\s*"(\w+)"[^}\n]*?ramMB:\s*(\d+),\s*cpuCores:\s*(\d+),\s*diskGB:\s*(\d+)[^}\n]*?priceCents:\s*(\d+)([^}\n]*)/g)){
    if(/direction:/.test(m[6]))continue; // 4-tier NEW tiers (staging-only)
    (seeds[m[1]+"|"+m[2]+"|"+m[3]+"|"+m[4]] ??= new Set()).add(+m[5]);
  }
}
const rows=fs.readFileSync("/root/nxeon-phase-custom-game-pricing/gameplans.csv","utf8").trim().split("\n").map(l=>l.split(","));
const ratios={};let unmatched=[];
for(const [f,c,r,d,p] of rows){const k=f+"|"+r+"|"+c+"|"+d;const s=seeds[k];if(!s){unmatched.push(k+"@"+p);continue;}
  const rs=[...s].map(sp=>(+p/sp).toFixed(3));(ratios[rs.join("/")] ??= []).push(f);}
for(const [k,v] of Object.entries(ratios))console.log("ratio",k,":",v.length,"rows",[...new Set(v)].join(","));
console.log("unmatched CSV rows (no seed with same family/spec):",unmatched.length,unmatched.join(" "));
'

